import type { BeginnerGuide } from './beginner-guidance';

const note = (why: string, mechanism: string, analogy: string, boundary?: string) => ({ why, mechanism, analogy, boundary });

export const tinyStoriesBeginnerGuidance: Record<string, BeginnerGuide> = {
  'transition-to-subwords': {
    background: 'Project 1 already established the repeating chain: text becomes token IDs; token IDs enter a model; the model emits next-token scores; training would compare those scores with known answers and update weights; inference instead samples from fixed weights. TinyStories preserves that chain but changes the size of the text pieces, the amount and origin of data, and eventually the size of the model.',
    picture: 'Shakespeare assembled text from single-letter and punctuation tiles. TinyStories introduces a box containing both small tiles and frequently useful larger pieces. A sentence can therefore fit on a shorter row, leaving room for more of the story inside the model’s fixed viewing area.',
    misconception: 'Changing to larger text pieces does not give the model vocabulary knowledge or grammar. The tokenizer only defines a reversible numbering system; useful prediction patterns still require weight updates during later training.',
    goal: 'Explain why the second project changes token scale, trace one story from source row to subword IDs and random logits, and distinguish a pipeline smoke test from pretraining.',
    notes: {
      departure: note('Character tokens are wonderfully transparent, but they consume many sequence positions. That limits how much of a story fits into one model calculation.', 'The tokenizer replaces common byte sequences with single IDs. The same context limit can then represent more visible text, while rare strings remain representable as smaller pieces.', 'Packing a suitcase with a mixture of folded garments and small loose items uses fewer slots than placing every thread in its own compartment.', 'Subword pieces are a storage and computation choice. They are not concepts in the model’s mind, and a longer visible passage does not guarantee that the model will use it well.'),
      question: note('A new project introduces several changes at once. Naming the exact learning question and what is not yet being tested prevents an early technical success from becoming an unsupported capability claim.', 'This lesson exercises every connection once with a bounded sample and random weights. Later lessons freeze data, tokenizer, batching and architecture separately before training begins.', 'A theatre performs a technical rehearsal to test lights, microphones and scene changes before judging the acting or the play.', 'A successful rehearsal proves the equipment connects; it does not prove the eventual performance will be good.'),
      source: note('Models reproduce statistical patterns from their supplied material, so authorship and generation process affect what can be learned and what claims are fair.', 'The TinyStories authors prompted larger language models to create simplified stories. We retain the source, split and recorded licence, then inspect the resulting text rather than treating “dataset” as a neutral box.', 'Before using a box of practice essays, a teacher asks who wrote them, under what instructions, and whether the same templates were reused.', 'Provenance reveals origin and constraints, not every hidden bias, error or duplicated idea in millions of generated stories.'),
      download: note('Downloading only convenient rows without recording which ones would make later comparisons impossible to reconstruct.', 'A fixed seed selects page offsets; each saved record keeps its original row number; the manifest records hashes. A hash changes when file bytes change, so it can detect a mismatch.', 'It is sampling numbered books from known library shelves and sealing an inventory with tamper-evident fingerprints.', 'A checksum detects changed bytes but cannot say whether the stories are correct, representative or ethically suitable.'),
      inspect: note('Training cost and evaluation credibility depend on story lengths, duplicates and split separation. These are data properties, not model settings.', 'The script counts stories, characters, simple whitespace-separated words, length percentiles and exact repeated texts separately for train and validation. The next audit will test subtler similarity across stories.', 'Before creating exam worksheets, count pages, find photocopies and ensure practice and exam piles are not the same stack.', 'Finding zero exact duplicates in 1,200 sampled stories does not prove the full dataset contains no duplicates or near-copies.'),
      tokenizer: note('The model needs a finite list of possible outputs. Whole words create an awkwardly huge list, while single characters create long sequences; BPE supplies a measurable compromise.', 'BPE begins with byte-level pieces and repeatedly joins frequent neighbours. The final file stores the vocabulary and merge rules so encoding and decoding follow the same procedure later.', 'A print shop starts with individual symbols, then creates reusable stamps for common combinations such as “ing” when repeated assembly wastes space.', 'The algorithm follows frequency, not grammar or meaning. A merged piece may look like a word or syllable without representing one linguistic idea.'),
      'random-model': note('Running before training creates the control condition needed to show that later structure came from updates rather than from the architecture or decoding software.', 'Seeded random numbers fill embedding, attention, feed-forward and output matrices. Token IDs flow through those matrices and produce one raw score for each vocabulary entry.', 'A newly wired sound mixing desk can pass a signal before its thousands of knobs have been adjusted for the concert.', 'The desk comparison explains adjustable state, but the model has no operator listening inside it and no intention behind its random scores.'),
      invoke: note('“The model ran” can mean either a forward calculation or a training update. This lesson isolates forward inference so the distinction is visible.', 'Eight sequences enter as integer arrays; the model returns a score grid; loss reads how poor the random scores were. During generation, one sampled ID is appended repeatedly. No backward calculation or stored weight changes occur.', 'A printer can produce a page from its current settings; measuring the bad print does not recalibrate it unless a separate correction step changes the controls.', 'Sampling adds pseudo-random variation to visible text, but it does not teach the model and should not be mistaken for creativity.'),
      'limits-next': note('A trustworthy experiment ends by separating what its evidence answers from attractive questions it has not tested.', 'We mark each pipeline connection as working, retain the random checkpoint, and leave dataset quality, tokenizer choice, architecture choice and learned story quality open for controlled lessons.', 'A pre-flight checklist can establish that engines, instruments and controls respond while still refusing to certify the entire journey complete.', 'Passing the checklist reduces known engineering risk; it neither guarantees safe data nor predicts final model quality.'),
    },
  },
  'dataset-audit': {
    background: 'A language model does not read a dataset as a human editor would. During training it receives token sequences and adjusts weights whenever doing so makes those supplied sequences easier to predict. If copied exam material, broken characters, or highly repeated templates enter that stream, the same correction machinery will learn from them without raising an objection. This lesson therefore examines the text and the train/validation boundary before either becomes a fixed input to later experiments.',
    picture: 'Imagine preparing a teaching workbook and a separate exam. First inventory every page, check for damaged printing, compare the exam against the workbook for copied passages, count overused worksheet templates, and then seal both piles with labelled bands. The seal does not certify that every lesson is wise; it makes later experiments use the same known material.',
    misconception: 'Finding zero exact or highly similar train/validation pairs does not prove that the stories are diverse, safe, unbiased, factual, or representative. It answers one leakage question at one declared threshold. Template repetition and content suitability require different evidence.',
    goal: 'Distinguish file integrity, split leakage, template repetition, content triage and dataset freezing; explain what each check detects, what it misses, and why no model weights change in this lesson.',
    notes: {
      'why-audit': note('Training converts repeated prediction errors into weight changes, so defects in the teaching material become part of the learning signal rather than an error message.', 'We inspect source identity, text structure, duplication and split separation before learning tokenizer merges or model weights. This keeps data failures from masquerading as modelling results.', 'A photocopier reproduces a stain on every source page perfectly; it cannot decide that the stain was not part of the lesson.', 'The audit tests declared failure patterns. It cannot discover every harmful idea, subtle bias or paraphrased copy.'),
      'freeze-inputs': note('Measurements are meaningful only if they refer to identifiable input bytes. Otherwise a changed download could inherit an old audit report.', 'The manifest records source rows and selection settings. SHA-256 compresses each complete file into a fingerprint; recomputing it detects even a one-byte change before analysis continues.', 'Record the serial numbers of two sealed exam boxes and compare their tamper-evident seals before accepting the examiner’s report.', 'Matching fingerprints prove byte identity, not truth, quality, legality or representativeness. Those are separate questions.'),
      command: note('The kind of program being run determines what can possibly have changed. Here we need an examiner, not a trainer.', 'The Python script reads JSON and tokenizer files, performs counting and comparisons, and writes a report. It never constructs a neural model, computes logits, gradients or optimiser updates, so there are no weights for it to teach.', 'A librarian can catalogue, compare and label books without rewriting any of their pages.', 'The script still creates evidence and configuration files; “read-only audit” describes its treatment of source data and model weights, not an absence of all output.'),
      integrity: note('Malformed rows can crash later code or quietly change token statistics, while unusually long stories can occupy many more training windows than typical ones.', 'Schema checks enforce expected fields and types. Character checks find replacement markers and hidden controls. Length thresholds create review flags, leaving any deletion for a separately recorded decision.', 'Inspect worksheets for blank pages, damaged symbols and unusually thick booklets before stacking them into equal classroom trays.', 'An outlier is a prompt to inspect, not proof of corruption. Automatically removing it would create a new dataset version.'),
      leakage: note('Validation is meant to act like unseen exam material. If near-copies of its stories appear in training, a model can appear to generalise by remembering familiar wording.', 'After exact and normalised matching, each story becomes a set of overlapping five-word strips. Jaccard similarity divides shared strips by all distinct strips in either story; all 200 validation stories are compared with all 1,000 training stories.', 'Cut each essay into overlapping five-word transparencies, then measure how much of two transparency piles is shared.', 'The 0.80 threshold detects heavy wording overlap, not meaning. A paraphrase can carry the same plot with few matching strips, while short formulaic phrases can match without making whole stories duplicates.'),
      templates: note('Leakage and narrow style are different. Unique stories can still repeatedly teach the same opening rhythm, making early fluency easier to imitate than long-range story consistency.', 'The audit counts the normalised first five words and selected recurring phrases independently of whole-story similarity. In the training sample, 610 of 1,000 stories start “once upon a time there.”', 'A thousand distinct forms may contain different answers while all beginning with the same printed heading and paragraph frame.', 'Template counts describe visible repetition; they do not measure every kind of plot, character, cultural or linguistic diversity.'),
      'content-screen': note('A dataset described as simple may still mention injury, fear or conflict. Locating likely examples helps a human decide what requires closer review.', 'Declared word lists act like an index: if a story contains one listed term, its category count rises. Context is not interpreted, so the result is a queue for inspection rather than a verdict.', 'A library search for books containing “fire” finds both dangerous-fire stories and fire-safety guides; a reader must still inspect them.', 'No hit means only that the listed words were absent. It does not mean the story is safe, appropriate or free of coded and contextual issues.'),
      'tokenizer-check': note('Later lessons rely on the tokenizer as the courier between text and IDs. We first confirm that it does not lose or replace content on either split.', 'Every story is encoded to IDs and decoded again. The decoded version is compared with the same declared Unicode normalisation, while unknown IDs and tokens per story are counted.', 'A courier translates every worksheet into numbered parcels and back; the returned worksheet should match the agreed printing standard.', 'Perfect round trips prove representability, not efficiency or learnability. A poor vocabulary can preserve every character while using wastefully long sequences.'),
      decision: note('Controlled comparisons require a stable input. If the stories change while vocabulary size or architecture changes, we cannot tell which cause produced the result.', 'The verified files, hashes and audit settings receive the name tinystories-development-v1. Later development lessons reuse that identity until an explicit, versioned scaling-data decision replaces it.', 'Seal and label one workbook/exam pair for laboratory trials, while keeping approval of the full school curriculum as a later decision.', 'The freeze is scoped to fast development experiments. This 1,200-story slice is not the final corpus and says little about the complete two-million-story distribution.'),
    },
  },
  'tokenizer-experiment': {
    background: 'The recurring course chain begins with text → token IDs. That first conversion controls how many sequence positions the model receives and how many different next-token scores it must produce. BPE training changes only this numbering-and-segmentation system: it counts recurring neighbouring text pieces and saves merge rules. It does not run the prediction → loss → gradient → weight-update part of the chain.',
    picture: 'Imagine choosing a parts catalogue for printing stories. A small catalogue stocks mostly tiny letter fragments, so one page needs many pieces but the storeroom and choice board stay small. A larger catalogue stocks common words and fragments as ready-made pieces, shortening assembly while expanding both storage shelves and the list of possible next pieces.',
    misconception: 'The vocabulary with the fewest tokens is not automatically the best. Larger vocabularies also enlarge model layers, learn increasingly specialised pieces from a small sample, and may behave differently after the corpus grows. This lesson chooses a documented development trade-off, not a universal optimum.',
    goal: 'Explain why vocabulary size affects both sequence length and model parameters, trace how each BPE candidate is trained and tested without neural-model updates, and defend the declared rule used to freeze one tokenizer.',
    notes: {
      question: note('Tokenization is not neutral plumbing: its piece inventory defines the model’s input labels, output choices and the amount of visible text fitting in a context window.', 'For the same source text, every candidate builds a different inventory of reusable pieces. Encoding chooses IDs from that inventory; the eventual model must produce one next-token score for every inventory entry.', 'Choose between a small box of general printing blocks and a large box containing many ready-made word fragments.', 'The pieces are statistical conveniences rather than ideas understood by the model, and shorter assembly does not guarantee better learned behaviour.'),
      'fixed-inputs': note('If both data and vocabulary recipe changed, a difference in token counts would have two possible causes and the comparison would stop being controlled.', 'Hashes lock both JSONL files. All candidates receive identical training strings, NFKC normalisation, byte-level starting pieces, merge-frequency rule and special-token order; only the vocabulary-size limit changes. Validation strings are withheld until the merge tables are finished.', 'Test four sizes of storage cabinet while keeping the same books, cataloguing rule and exam pile.', 'A fixed small sample makes candidates comparable here but does not establish which vocabulary a much larger corpus would learn.'),
      tooling: note('One shared implementation prevents accidental differences in splitting or decoding from masquerading as a vocabulary-size effect.', 'The Python binding sends training strings and configuration to the Tokenizers library. Its BPE trainer counts adjacent pieces, adds frequent merges, and serialises the resulting inventory, merge rules, normaliser and decoder into each JSON artifact.', 'The same automated print shop receives four different shelf-size limits; its machines and work order remain unchanged.', 'The library executes deterministic counting rules. It does not inspect semantics or decide which fragments are linguistically sensible.'),
      command: note('A reproducible choice needs candidate artifacts and selection settings, not only a winning number printed to the terminal.', 'The script verifies prior evidence, trains four tokenizer objects, saves every candidate, evaluates both splits, copies the selected candidate to tokenizer.json, and atomically replaces the local dashboard JSON. No MLX model is constructed.', 'A laboratory keeps every tested lens, the calibration sheet and the selected lens rather than recording only “lens B looked best.”', 'Files and metrics change on disk, but there are no neural weights or optimiser state in this experiment.'),
      integrity: note('Compression is worthless if IDs cannot reconstruct the supplied text or structural markers move to unexpected numbers.', 'Each story travels text → IDs → decoded text. Unknown IDs and mismatches are counted, while pad, unknown, beginning and end token IDs are compared with 0–3. Any failure removes that candidate before cost comparisons.', 'Translate every page into parcel numbers and back before comparing how many parcels each scheme used.', 'Matching returned pages proves a reversible representation under NFKC; it does not preserve distinctions that NFKC itself intentionally normalises.'),
      compression: note('Transformer work is organised by token positions, so representing the same story with fewer tokens can expose more prose per context and reduce the number of training positions.', 'The script divides source-character count by ordinary token count and also records the distribution of tokens per story. Validation numbers reveal how merge rules learned from training text transfer to withheld stories.', 'Count how many printed characters each reusable tile covers and how many tiles a typical or unusually long page needs.', 'Characters per token depends on this language and corpus. It is not a direct speed, memory or quality measurement.'),
      'model-cost': note('Every additional vocabulary entry requires learned input numbers and an additional next-token output choice, so sequence savings are not free.', 'For width 256, an entry adds 256 embedding weights, 256 output weights and one output bias. Multiplying 513 by the vocabulary size gives the exact vocabulary-facing count for this untied design.', 'Each catalogue entry needs both a storage card on the incoming shelf and a row on the outgoing voting board.', 'The calculation omits positions, attention, feed-forward layers and training activations; it is deliberately a model-interface proxy.'),
      decision: note('Choosing after admiring results invites convenient storytelling. A threshold written into code makes the course preference inspectable and repeatable.', 'Every candidate must pass integrity. A smaller vocabulary may replace 2,048 only with at most 10% more validation tokens; a larger one needs at least 20% fewer. Otherwise the existing 2,048 interface remains selected.', 'Set the minimum fuel saving required to justify buying a larger engine before opening the test results.', 'The thresholds encode priorities rather than a law of language modelling. Downstream matched training can later challenge the decision.'),
      'freeze-next': note('Later batching and model comparisons need token IDs to retain the same meaning. Otherwise a changed tokenizer would alter both examples and architecture size mid-experiment.', 'The selected JSON and checksum become the versioned interface used to add story boundaries and construct causal windows. A future corpus change triggers a new tokenizer experiment rather than silently replacing the file.', 'Seal the chosen parts catalogue before comparing packing methods, then issue a new catalogue version if the entire warehouse inventory changes.', 'Freezing aids controlled development; it is not a promise that this vocabulary remains best for all data, languages or architectures.'),
    },
  },
  'sequence-batching': {
    background: 'The course chain is now text → token IDs → training examples → model. The tokenizer produces a different-length ID list for every story, while fast model calculations expect equal-sized numeric rectangles. Batching is the conversion between those forms. It determines which earlier IDs accompany each next-token answer, so an error here changes what the future model is taught even though no model exists yet.',
    picture: 'Picture differently sized story worksheets entering a classroom with 32 identical trays, each containing 128 question seats. Every story receives a START and END card, each answer strip is moved one seat left, and unused seats are filled with blank cards hidden from the marker. A divider prevents one story from becoming another story’s context.',
    misconception: 'A nearly full batch is not automatically a better batch. Naïvely joining stories wastes fewer tensor positions but invents relationships at their boundaries. Also, the causal mask and loss mask are different covers: one prevents looking ahead; the other tells the marker to ignore padding.',
    goal: 'Trace one story from token IDs into aligned inputs and targets, explain overlap and padding, distinguish causal visibility from loss grading, and defend the selected boundary policy using the saved audit.',
    notes: {
      'why-batching': note('Accelerators gain efficiency by applying the same operation to many equal-shaped examples, but the source stories do not naturally form a rectangle.', 'The batcher maps each variable-length story into fixed 128-position rows and later groups 32 rows. Axis zero means examples and axis one means ordered token positions.', 'Place 32 worksheets into identical 128-seat trays so one marking machine can process the same seat across every tray together.', 'Rectangular shape makes parallel calculation possible; it does not prove that the examples inside are semantically valid.'),
      boundaries: note('If separate stories are simply joined, the model receives an invented question—what follows one story’s ending?—and may inspect unrelated earlier prose.', 'BOS and EOS wrap every encoded story. Windows are constructed inside that wrapper only, so EOS is a legitimate ending answer while the next story begins in a fresh example.', 'Give every worksheet a START cover and END cover, then place a physical divider before the next student’s worksheet.', 'Markers define our data policy. They do not make the model understand beginnings or endings before training.'),
      'shifted-targets': note('Next-token learning needs both the visible token at each seat and the known token that truly followed it.', 'From one 129-ID slice, positions 0–127 become inputs and positions 1–128 become targets. The one-place displacement aligns every input prefix with its immediate answer.', 'Photocopy a numbered sentence strip, slide the answer copy one square left, and compare each square with the next word.', 'The target is supplied only to calculate loss. A causal model must not inspect later target information through attention.'),
      windowing: note('Long stories exceed one 128-position row, and an off-by-one slicing error could silently skip or duplicate a prediction pair.', 'Slices start 128 tokens apart but each reads 129 tokens. The endpoint appears as the next slice’s first input, preserving the boundary pair exactly once; reconstruction and pair counts verify the rule.', 'The final word on one worksheet becomes the heading on the next worksheet, so the join question survives without marking it twice.', 'Only one token crosses the chunk boundary. The model still loses access to the rest of the preceding chunk.'),
      padding: note('The final story chunk rarely fills every seat, yet the tensor row must retain the same width as every other row.', 'PAD IDs fill right-hand cells. A parallel row of ones and zeros labels real and filler targets, so future loss arithmetic includes only the ones.', 'Blank index cards fill unused tray seats so trays stack evenly; opaque grading stickers tell the marker to skip those cards.', 'PAD is structural filler rather than prose. If masking fails, the model can waste capacity learning artificial padding patterns.'),
      'causal-mask': note('Two unrelated problems require two masks: future answers must be invisible, and filler answers must be ungraded.', 'The causal attention mask blocks columns to the right of each position. The loss mask leaves attention logic alone and multiplies padded per-position errors by zero before averaging.', 'One cover blocks a student’s view of later answers; a different marking stencil tells the teacher which blank boxes not to score.', 'A correct loss mask does not prevent information leakage through attention, and a correct causal mask does not remove padding from the loss.'),
      command: note('A reproducible batch contract needs verified inputs, saved settings, decoded examples, and machine-checkable invariants rather than only a printed shape.', 'The script verifies prior checksums, encodes stories, builds and audits examples, shuffles training indices reproducibly, materialises MLX arrays, then atomically writes local evidence and configuration.', 'A packing inspector checks the sealed catalogue and workbook, fills sample trays, recounts every question, and files both the procedure and photographs.', 'This command writes evidence files but constructs no transformer and performs no forward pass, gradient, optimiser update, or checkpoint save.'),
      evidence: note('Efficiency must be interpreted beside correctness: an almost-full tray is a poor bargain if it mixes two unrelated worksheets.', 'The dashboard reports valid-position utilisation, cross-story targets, pair reconstruction, tensor shapes, and a decoded EOS-to-padding boundary for both the selected and naïve methods.', 'Compare a partly empty tray with intact dividers against a full tray where the last sentence of one child’s essay is stapled to the first sentence of another’s.', 'Zero detected boundary targets validates the implemented rule on these files; it does not establish that this is the fastest possible correct packing algorithm.'),
      'freeze-next': note('The random baseline and every later training comparison need identical definitions of an example, or apparent model differences could actually come from changed batching.', 'We freeze context 128, batch size 32, story isolation, one-token overlap, right padding, loss masking, and causal visibility as the development contract.', 'Seal the tray diagram and marking stencil before testing different untrained machines on the same worksheets.', 'This freeze supports controlled development. A later segment-aware packing experiment may replace it only as an explicit measured change.'),
    },
  },
  'random-gpt-baseline': {
    background: 'The course chain has reached text → tokens → batches → logits, but it has not yet entered loss → gradients → updates. Architecture is the fixed arrangement of calculations; weights are the adjustable numbers inside that arrangement. This lesson assembles the exact arrangement intended for training, fills its weights with repeatable random values, measures its untouched output, and saves that state so training has an honest “before” photograph.',
    picture: 'Imagine building a six-floor sound-processing desk. Each floor has eight routing panels and a larger private processing bench. The desk is fully wired, but its 5.82 million dials begin at arbitrary factory positions. We pass three recordings through it, measure the distorted output, photograph every dial as checkpoint zero, and only later begin calibration.',
    misconception: 'A large parameter count, a successful forward pass, and occasional recognisable words do not mean the model already knows anything. The tokenizer supplies recognisable word fragments, while random matrices can join them accidentally. Learning begins only when prediction error produces gradients and an optimiser changes weights.',
    goal: 'Explain the difference between architecture and weights, defend the baseline size rule, trace a full forward-only evaluation and prompt generation, and explain why exact checkpoint reload matters before the first update.',
    notes: {
      'why-baseline': note('Without an exact before-state, later improvement could be credited to training even if tokenizer, batch rules, architecture, or prompts changed at the same time.', 'The lesson fixes all input and model contracts, invokes them with zero updates, and saves metrics plus weights under one run identity. Later checkpoints can be compared against the same control.', 'Photograph a new instrument, record its untuned sound, and seal the test music before a technician adjusts it.', 'A baseline provides comparison evidence; it does not guarantee that the chosen architecture will train well or reach useful quality.'),
      'size-choice': note('Width and depth change both what patterns the model can represent and how much memory and computation every update consumes.', 'An exact formula counts embedding, attention, feed-forward, normalisation, and output arrays for three widths. The rule selects the smallest count inside the previously declared 5–15M range.', 'Choose the smallest engine that meets a declared capacity class before paying for a larger engine without road-test evidence.', 'Parameter count is a size measure, not horsepower or quality. Two architectures with equal counts can learn differently.'),
      architecture: note('A pile of weights is not yet a model; their placement determines which inputs multiply which numbers and where information can travel.', 'Token and position embeddings form one vector per seat. Six blocks alternate causal routing across seats with private nonlinear processing at each seat, then an output layer produces 2,048 scores per seat.', 'Six workshop floors repeat the same layout: eight couriers route permitted notes, then each desk processes its own combined bundle.', 'The couriers and desks are mapped calculations. No component reads, routes, or understands with human intention.'),
      'random-state': note('Training needs a non-identical starting point so different units can develop different numerical roles, but the start must be reproducible enough to audit.', 'MLX uses seed 42 to create pseudo-random arrays and materialises them on the GPU. Counting occurs only after the lazy arrays have actually been evaluated.', 'Issue the same numbered factory setup card so a control panel receives the same initial dial positions on a repeat build.', 'Reproducibility can vary across software or devices, and a seed does not make the initial weights good or meaningful.'),
      validation: note('A generated sample can be unusually funny or plausible by chance; grading every held-out target gives a much broader numerical control.', 'Each validation batch produces logits, cross-entropy is calculated per position, the loss mask removes padding, and all real-position errors are summed before one average is reported. No backward graph is used to update weights.', 'Mark every real answer in a sealed exam while placing a stencil over blank filler boxes, then average the marks without returning corrections to the student.', 'The examiner comparison stops at information flow: the arithmetic has no judgement, and validation has already been used for development rather than serving as a pristine final test.'),
      prompting: note('Loss summarises many known answers but does not show what repeated next-token sampling looks like to a reader.', 'A prompt becomes IDs; the final logits become probabilities; a seeded categorical draw appends one ID; and the loop repeats with unchanged weights. The top-five view exposes how flat the initial preference is.', 'An untuned weighted spinner selects one tile, adds it to the strip, then spins again using the longer strip as input.', 'The draw is numerical sampling, not creative choice. Recognisable pieces come from the tokenizer catalogue and can align accidentally.'),
      checkpoint: note('A checkpoint is useful only if it can reconstruct the same numerical behaviour later. A file existing on disk is not enough evidence.', 'Weights are serialized to Safetensors with named arrays and a checksum. A fresh matching architecture loads them strictly and recomputes a fixed logit slice; any difference fails the experiment.', 'Record every dial under labelled names, rebuild the desk, restore the labels, and compare a calibration signal exactly.', 'The file does not contain the Python architecture, tokenizer, dataset, or interpretation; those remain separate configuration requirements.'),
      command: note('Reproducibility requires knowing which earlier artifacts were trusted and which new state was written.', 'The command verifies data and tokenizer fingerprints, reconstructs fixed windows, runs forward calculations and generation, then writes learner-local JSON, configuration, and checkpoint files. It never constructs an optimiser.', 'An inspector checks seals on the workbook and parts catalogue before running a documented factory acceptance test and filing its outputs.', 'Files and MLX cache state change on disk and in memory, but random model weights never change after initial materialisation.'),
      evidence: note('Different measurements answer different questions: loss tests next-token scoring, samples expose visible behaviour, memory tests feasibility, and reload parity tests artifact integrity.', 'The dashboard reads the active evidence source and places those measurements together while retaining their separate labels and limitations.', 'A vehicle inspection uses a brake reading, road sample, fuel gauge, and serial-number check; no single dial substitutes for the others.', 'All evidence describes one seed, architecture, data slice, software path, and forward-only run. It does not predict trained quality or full training memory.'),
      'freeze-next': note('The first update becomes interpretable only if it changes the correction loop and nothing else about the before-state.', 'Lesson 6 will load or recreate the exact architecture contract, feed the same style of masked batches, calculate gradients, apply optimiser updates, and capture early checkpoints against checkpoint zero.', 'Lock the instrument, test recording, and measurement protocol; then allow the technician to change only dial positions according to correction readings.', 'Even a controlled first run can expose instability or insufficient data. Freezing inputs improves diagnosis rather than guaranteeing success.'),
    },
  },
  'first-pretraining': {
    background: 'The complete model already turns token IDs into next-token probabilities, but checkpoint zero contains arbitrary weight values. Training closes a feedback loop around that existing forward calculation: compare predictions with known next tokens, calculate how each weight affected the error, apply a small numerical correction, and try again. Repetition—not a new language module—creates the learned behaviour.',
    picture: 'Picture a 5.82-million-dial mixing desk receiving batches of story fragments with the correct next pieces printed on a hidden answer strip. After each attempt, an automatic tracing system places a tiny slope arrow beside every dial. AdamW combines today’s arrows with recent arrow history, nudges the dials, and sends in the next tray. Checkpoint photographs reveal how the sound changes during calibration.',
    misconception: 'A lower loss does not mean the model has acquired human understanding or a complete story plan. It means its numerical probability assignments became better, on average, for next tokens from this measured distribution.',
    goal: 'Trace one update from a masked batch through logits, loss, gradients, AdamW, changed weights, staged evaluation, and visible prompt output while keeping the random control and evidence limits explicit.',
    notes: {
      meaning: note('The word “pretraining” can sound as though knowledge is installed before the real work begins. It is itself the main prediction-training phase, described relative to possible later specialisation.', 'The model repeatedly predicts the next subword in general training stories. No labels such as plot, grammar, or moral are supplied; those regularities can influence weights only insofar as they help predict tokens.', 'A musician first practises across the whole course songbook before any later rehearsal for one narrow performance.', 'Our “whole songbook” is only 1,000 synthetic stories, so broad learning here is broad relative to a later task—not broad relative to language or the world.'),
      'inherit-control': note('A before-and-after comparison is trustworthy only if both sides begin with the same measured object.', 'Checksums identify the exact data, tokenizer, and checkpoint bytes. Strict loading maps every named tensor into the same architecture, and step-zero validation repeats the old exam before corrections begin.', 'Return the same photographed instrument to the same test room rather than assembling a supposedly similar instrument from the same instruction sheet.', 'Matching hashes establish identity, not quality. They also do not promise bit-identical computation on every future hardware or library version.'),
      'data-order': note('A batch update blends evidence from several windows. Which windows arrive together changes the short sequence of correction directions even when the overall dataset is unchanged.', 'A seeded shuffle deals every window once, includes the final incomplete hand, then reshuffles for the next pass. The saved seed makes this deal reproducible within the documented software path.', 'Shuffle a deck, deal every card including the short last hand, then gather and reshuffle—rather than drawing with replacement and accidentally skipping half the deck.', 'Equal coverage does not make neighbouring updates independent, and exact shuffle reproduction alone cannot remove floating-point or hardware variation.'),
      loss: note('Padding exists only to make rectangular tensors. Grading it would reward mastery of the storage container instead of story prediction.', 'Cross-entropy scores every position, a parallel one-or-zero mask erases filler-position errors, and division by the count of ones produces the mean over genuine targets.', 'A marking stencil exposes printed exam questions and covers blank boxes that were added only so every sheet fits the scanner.', 'The mask prevents padding from affecting loss; it does not itself control which earlier tokens attention can see. The separate causal mask handles future visibility.'),
      gradients: note('One loss number reports the batch’s overall error but offers no direct instruction for millions of adjustable values.', 'Automatic differentiation applies the chain rule backward through every multiplication, addition, normalisation, and nonlinear operation. Each resulting derivative estimates the local loss change from a tiny movement of one weight.', 'A contour map adds a small downhill arrow at your current location; it helps choose the next step without revealing the entire mountain range or destination.', 'Gradients are local numerical slopes. They can be noisy, can interact, and do not contain concepts, intentions, or a guarantee of reaching the best solution.'),
      optimizer: note('Following every raw gradient with the same scale can make noisy coordinates wobble or let a few consistently large values dominate.', 'AdamW keeps moving averages of each gradient and its square, uses them to scale coordinate-wise movement, then separately applies weight decay. The fixed learning rate multiplies the resulting step.', 'A foreman consults both today’s direction arrows and a short logbook of recent arrows before moving each dial, while a gentle spring discourages unchecked drift.', 'AdamW is an arithmetic rule, not a teacher who understands language. A plausible default rate and decay still require measured comparison.'),
      checkpoints: note('Showing only the final sample hides whether useful structure appeared gradually, suddenly, or after an unstable phase.', 'At declared update counts, training pauses; every held-out window is scored; fixed prompts are sampled; and weight tensors are serialized with hashes. The zero stage points to the original baseline file.', 'Photograph the same restoration after the first brush stroke, early cleaning, mid-course work, and final pass under the same lighting.', 'These photographs save dial positions but not AdamW’s logbook or the dealer’s place in the shuffled deck, so exact training cannot yet resume from them.'),
      command: note('A training command consumes prior artifacts and creates significant new state, so learners should know both sides before executing it.', 'The script verifies prerequisites, constructs arrays on the Apple GPU through MLX, runs forward and backward graphs, updates weights, saves local checkpoints, and atomically refreshes dashboard JSON after each evaluation.', 'A laboratory work order lists sealed inputs, machinery, transformations, inspection stops, and output shelves before the machine starts.', 'The command changes learner-owned files and uses compute and unified memory. It deliberately cannot overwrite committed reference results.'),
      evidence: note('One generated paragraph is vivid but statistically fragile; one aggregate number is broad but hard to feel. They answer complementary questions.', 'Validation loss averages probability error over every genuine held-out target. Fixed prompts traverse one seeded sample path at each checkpoint. Reading both connects systematic predictive change with visible behaviour.', 'Use an entire marked exam to judge consistency and a recorded recital to hear the character of one performance.', 'A lower exam error and cleaner recital do not test factual truth, safety, novel plots, other domains, or every possible sampling seed.'),
      'limits-next': note('Fast improvement on a small repeated corpus can eventually become memorisation, and weight files alone are insufficient for interruption-safe training.', 'The run records held-out loss and data exposure, then stops at a modest budget. The next lesson will preserve optimiser moments, update count, and shuffle position so interruption and exact continuation can be tested.', 'A workshop has useful progress photographs but still needs to save the foreman’s logbook and mark the precise next worksheet before safely closing overnight.', 'Resumability improves engineering reliability, not model quality. Recipe tuning and larger data remain separate later questions.'),
    },
  },
  'checkpoints-dashboard': {
    background: 'Training is not one calculation but a sequence of dependent updates. The model weights entering update 551 came from update 550; AdamW’s moving averages summarize earlier gradients; and the next batch depends on how far a shuffled list has already been consumed. A resumable checkpoint must preserve this whole continuation state, not merely the arrays used to generate text.',
    picture: 'Imagine pausing a long board game. Photographing the board preserves piece positions, but exact continuation also needs the current player, turn number, cards already dealt, order of the remaining deck, and any running score modifiers. The manifest is the sealed inventory saying every required part made it into the save box.',
    misconception: 'Matching seeds and model weights do not automatically reproduce the next update. A seed restarts a pseudo-random sequence, AdamW has history outside the model, and separate GPU processes may differ by tiny floating-point amounts even after identical saved state is restored.',
    goal: 'Explain which state a training restart needs, how incomplete saves are rejected, why serialization integrity and cross-process numerical reproducibility are separate tests, and which live metrics diagnose operation rather than model quality.',
    notes: {
      'reliability-question': note('A weight-only file is sufficient for inference because inference reads weights without calculating an optimiser update. Training’s next action depends on additional histories and cursors.', 'A complete save combines current model tensors, AdamW tensors, trainer counters, shuffled order, random-generator state, and a manifest. A loader reconstructs each before selecting the next batch.', 'A board-game photograph preserves pieces, while a proper pause box also stores whose turn it is, the score sheet, and the ordered deck.', 'The game comparison describes dependent state. The model is not playing strategically, and checkpoint files do not contain human-readable memories or intentions.'),
      'honest-boundary': note('Missing history cannot be inferred reliably from the final weights because many different update paths can arrive at similar or identical model values.', 'Lesson 6 saved model tensors but discarded AdamW moments and the shuffle cursor. Lesson 7 therefore declares a new segment, initializes those once, and tests continuation only after they have been captured.', 'A photograph of a car’s location cannot reconstruct the exact engine temperature, fuel-flow history, or last gear if those instruments were never recorded.', 'Starting a new recorded segment is honest but changes the optimiser trajectory; its later quality must not be presented as seamless Lesson 6 continuation.'),
      'checkpoint-anatomy': note('Different future operations need different saved facts, and separating them makes omissions inspectable.', 'Safetensors files hold named model and optimiser arrays. JSON holds small counters, a permutation, cursor, and random state. The manifest lists expected files, sizes, hashes, schema, and protocol identity.', 'Pack machinery, the foreman’s logbook, the numbered work queue, and a sealed packing list into labelled cases.', 'Four files are a design choice, not a universal checkpoint law. Another framework may package equivalent state differently while needing the same information.'),
      'optimizer-state': note('AdamW scales a new gradient using moving summaries of earlier gradients, so resetting those summaries changes the proposed update even if model weights and batch match.', 'The nested optimiser tree contains a step counter, scheduled values, and first/second-moment tensors aligned with model parameters. Flattening gives each array a serializable name; unflattening rebuilds the nested structure.', 'A navigator combines today’s wind reading with rolling logs from previous minutes; discarding the log changes the next correction.', 'AdamW performs arithmetic without understanding a destination. Its log is numerical history, not episodic memory or stored prose.'),
      'data-state': note('A seed tells a random generator how to start, not where it currently is after many draws. Restarting from the seed can repeat earlier batches and omit later ones.', 'The trainer stores the current shuffled permutation, cursor, completed passes, and complete Python random state. After loading, invariant checks validate the permutation and preview the next batch without advancing the real cursor.', 'Saving only a deck’s original shuffle instruction differs from saving the exact remaining deck and dealer’s finger position.', 'A matched next batch proves order continuity at that point. It does not make floating-point GPU calculations bitwise deterministic.'),
      'safe-save': note('A sudden stop between large writes can leave a directory that looks plausible but combines missing, truncated, or stale files.', 'The writer creates the tensor and JSON parts, hashes their completed bytes, then writes the manifest last. The loader treats absence or mismatch as a hard failure instead of guessing which parts are usable.', 'A shipping clerk seals the packing list only after checking every labelled case; an unsealed shipment is not released.', 'The completion marker detects partial state but cannot prevent hardware failure, filesystem corruption after hashing, or loss of the entire storage device.'),
      'parity-design': note('A checkpoint existing on disk does not prove that loading it preserves future behaviour; a matched control is needed.', 'One route saves and continues in memory. The other loads that exact save in a new process. Discrete batches must match exactly, serialized tensors must reload exactly, and later floating-point outputs are compared with pre-recorded bounds.', 'Send two runners from the same timed checkpoint: one never leaves the track, while the other pauses, records every condition, and restarts from the marked line.', 'GPU arithmetic can differ slightly between processes, so “same method” need not mean identical final bits. Tolerances must remain explicit and cannot excuse different batches or missing state.'),
      command: note('The process boundary is part of the claim, so a single in-memory function call would not adequately test reconstruction from disk.', 'The orchestrator writes a protocol and launches workers as separate Python processes. Each verifies input hashes and reconstructs data/model objects. Live JSON updates every ten steps; complete checkpoint files stay in ignored learner storage.', 'A fire drill requires leaving and re-entering through the documented route, not merely imagining the evacuation while remaining at a desk.', 'A simulated clean exit after a completed save does not test power loss during every possible file-write instruction.'),
      evidence: note('A monitoring number can be useful for detecting a stalled or exploding run without being a reliable score of model quality.', 'Per-batch loss and gradient norm update frequently and vary with batch contents. Full validation averages every held-out target at endpoints. Parity fields report state integrity and numerical divergence separately.', 'A car dashboard shows speed and engine temperature during travel; a controlled inspection after arrival answers a different question about overall condition.', 'Smooth live curves do not prove generalisation, and a tiny parity difference does not imply meaningful quality change without endpoint evaluation.'),
      'limits-next': note('Engineering reliability makes longer comparisons safer, but extra updates performed during a systems test can overfit or follow a newly reset optimiser path.', 'Step-600 validation is compared with step 500, but checkpoint validity is judged by continuity checks rather than whether quality improved. The next experiment freezes this state contract while changing recipe variables deliberately.', 'Testing whether a freezer restarts after a power cycle should not be mistaken for a recipe taste test simply because food remained inside.', 'A reliable checkpoint prevents lost progress; it cannot select a learning rate, add data diversity, or make generated stories logically coherent.'),
    },
  },
};
